// Minimal endless runner based on IDEA.md
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const cw = (canvas.width = canvas.clientWidth);
  const ch = (canvas.height = canvas.clientHeight);

  // ship
  const ship = { x: cw / 2, y: ch - 30, w: 20, h: 20, speed: 5 };
  let fuel = 100;

  // input
  const keys = { left: false, right: false };
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
  });

  // stars background
  const stars = Array.from({ length: 100 }, () => ({
    x: Math.random() * cw,
    y: Math.random() * ch,
    s: Math.random() * 2 + 0.5,
    speed: Math.random() * 0.5 + 0.2,
  }));

  // asteroids
  let asteroids = [];
  let lastSpawn = 0;
  const spawnInterval = 1000; // ms

  function spawnAsteroid() {
    const size = Math.random() * 20 + 20;
    asteroids.push({
      x: Math.random() * (cw - size),
      y: -size,
      w: size,
      h: size,
      speed: Math.random() * 2 + 2,
    });
  }

  function rectIntersect(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  let gameOver = false;

  function update(dt) {
    if (gameOver) return;
    // fuel
    fuel -= dt * 0.02; // drains
    if (fuel <= 0) { fuel = 0; gameOver = true; }
    // ship movement
    if (keys.left) ship.x -= ship.speed;
    if (keys.right) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(cw - ship.w, ship.x));
    // stars
    stars.forEach(s => {
      s.y += s.speed;
      if (s.y > ch) { s.y = 0; s.x = Math.random() * cw; }
    });
    // asteroids
    const now = performance.now();
    if (now - lastSpawn > spawnInterval) { spawnAsteroid(); lastSpawn = now; }
    asteroids.forEach(a => a.y += a.speed);
    asteroids = asteroids.filter(a => a.y < ch);
    // collision
    if (asteroids.some(a => rectIntersect(ship, a))) gameOver = true;
  }

  function draw() {
    ctx.clearRect(0, 0, cw, ch);
    // stars
    ctx.fillStyle = '#fff';
    stars.forEach(s => ctx.fillRect(s.x, s.y, s.s, s.s));
    // ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y);
    ctx.lineTo(ship.x + ship.w / 2, ship.y - ship.h);
    ctx.closePath();
    ctx.fill();
    // asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // fuel bar
    ctx.fillStyle = '#f00';
    ctx.fillRect(10, 10, fuel * 2, 10);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 200, 10);
    // game over
    if (gameOver) {
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', cw / 2, ch / 2);
    }
  }

  let last = performance.now();
  function loop() {
    const now = performance.now();
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
